-- CIDM-11284 Migrated Pending Purchase Authorizations Data Cleanup
/*
-- Issue Description: 
   MD CHESSIE migrated purchase authorizations in "pending" status were forwarded with the users (tosecurityusersid as '00000000-0000-0000-0000-000000000000'), 
   as a result, these records are not appearing on any supervisor or finance user dashboards.

-- Category/ Module: Service Log/ Purchase Authorization
-- Root cause: Data 
-- Fix Provided: One time data cleanup to forward these pending requests to the correct case supervisor 
--               or the finance approval requests should be updated to role-based requests for the LDSS finance team.
-- Pull request# N/A 
-- Is Code fix Required?: No
--	Code fix ticket#: N/A
--	Reason why no related code fix: N/A
--  Regression Impacts: N/A
*/

-- Fix Missing county code -- Baltimore City 
update tb_service_log 
	set ldss_cd = '1429', 
		update_user_id = 'CIDM-11284', 
		update_ts = now()
where service_log_id = 393622
	and delete_sw = 'N'
	and ( ldss_cd  is null or btrim(ldss_cd) = '' );	


-- Forwarded to Case Supervisor - Update fix Sup ID
-- from sandrak.jackson@maryland.gov -> Sup jill.latteri@maryland.gov
update cjams.routing 
set tosecurityusersid = '586909e6-04f0-4ca8-8434-0a046fbbbad8', 
	updatedby = 'CIDM-11284', 
	updatedon = now() 
where routingid = '6026817c-b06b-4c9d-8e44-c573d143d337' 
	and activeflag = 1;


-- Closed case 3003682	& Client # 2654247 - Service date: 05/23/2007	?/
update routing 
	set activeflag = 0, 
		updatedby = 'CIDM-11284', 
		updatedon = now()
where objectid = '7808'
	and eventcode in ('PCAUTH', 'PCAUTHR')
	and activeflag = 1
	and tosecurityusersid = '00000000-0000-0000-0000-000000000000' ;


